function uid(p){return p+crypto.randomUUID().slice(0,8)}function profile(id){return db.profiles.find(x=>x.id===id)}function task(id){return db.tasks.find(x=>x.id===id)}function opp(id){return db.opps.find(x=>x.id===id)}function pname(id){return profile(id)?.name||'Profil tidak ditemukan'}function actor(){return $('#role').value}function mine(a){return actor()==='Supervisor'||actor()==='Administrator'||a.owner===actor()}function visible(a){return a.filter(mine)}function isOpen(t){return !['Selesai','Dibatalkan'].includes(t.status)}function overdue(t){return isOpen(t)&&parseCRMDate(t.due)<new Date()}function nextTasks(id){return db.tasks.filter(t=>t.opp===id&&isOpen(t))}function hasNext(o){return nextTasks(o.id).length||o.review}function record(action,object,detail=''){db.audit.unshift({id:uid('H'),action,object,detail,actor:actor(),time:now()});localStorage.setItem(key,JSON.stringify(db));render()}
