function taskCard(t){return `<article class="record"><div class="recordtop"><span class="label">${E(t.type)}</span>${badge(overdue(t)?'Overdue':t.status)}</div><h3>${E(t.purpose)}</h3><p>${E(pname(t.profile))}</p><div class="meta">${E(t.owner)}<br>Jadwal ${fmt(t.scheduled)}<br>Deadline ${fmt(t.due)}</div><div class="actions">${btn('Buka Task',`go('Aktivitas detail','${t.id}')`)}${t.opp?btn('Peluang',`go('Opportunity detail','${t.opp}')`):''}</div></article>`}
