function renderContent(){let h='';let actions='';if(view==='Monitoring'){let os=visible(db.opps).filter(o=>o.outcome==='Aktif'),ts=visible(db.tasks),due=ts.filter(overdue),no=os.filter(o=>!hasNext(o)),stale=os.filter(o=>(Date.now()-new Date(o.entered))/86400000>db.config.aging);h=`<div class="intro"><div><span class="label">SUPERVISOR WORKSPACE</span><h1>Peluang yang perlu perhatian</h1><p>Temukan hambatan, tetapkan tindakan, pantau hasilnya.</p></div>${btn('Opportunity baru','newOpp()',true)}</div><div class="metrics">${[['Opportunity aktif',os.length,"go('Peluang')"],['Follow-up overdue',due.length,"go('Agenda');statusFilter='Overdue';renderContent()"],['Tanpa next action',no.length,"showException('next')"],['Stage stagnan',stale.length,"showException('aging')"]].map(([a,b,c])=>`<button class="metric" onclick="${c}"><span>${a}</span><strong>${b}</strong><small>Lihat detail ↗</small></button>`).join('')}</div><div class="split"><section class="panel"><h2>Follow-up terlambat</h2>${due.map(taskCard).join('')||empty('Tidak ada follow-up overdue.')}</section><section class="panel"><h2>Snapshot pipeline aktif</h2>${stages.map(st=>{let n=os.filter(o=>o.stage===st).length;return `<button class="stagebar" onclick="go('Peluang');stageFilter='${st}';renderContent()"><span>${st}</span><i style="width:${Math.max(4,n/Math.max(1,os.length)*65)}%"></i><b>${n}</b></button>`}).join('')}<p class="hint">Count opportunity saat ini. Nilai plafon, penempatan dana dan kontrak tidak digabung sebagai revenue.</p><h2>Aktivitas terbaru</h2>${visible(db.activities).slice(0,3).map(a=>`<div class="miniitem"><b>${E(pname(a.profile))}</b><p>${E(a.type)} · ${E(a.result)}</p></div>`).join('')}</section></div>`}
else if(view==='Leads'){actions=btn('Lead baru','createLead()',true);let a=db.leads.filter(l=>matches(l,pname(l.profile)+' '+l.need)&&(!month||l.created.startsWith(month))&&(statusFilter==='Semua'||statusFilter==='Aktif'&&!['Converted','Closed','CustomerConverted'].includes(l.status)||l.status===statusFilter));h=toolbar(filters()+`<select onchange="statusFilter=this.value;renderContent()">${options(['Aktif','Semua','New','In qualification','Converted','Closed'],statusFilter)}</select>`)+`<div class="records">${a.map(l=>`<article class="record"><div class="recordtop">${badge(l.status)}<span class="label">${E(l.source)}</span></div><h3><button class="textbtn" onclick="go('Lead detail','${l.id}')">${E(pname(l.profile))}</button></h3><p>${E(l.need||'Kebutuhan belum dicatat')}</p><div class="meta">${E(l.product)} · ${E(l.owner)}<br>Dibuat ${fmt(l.created)}</div>${btn('Buka lead',`go('Lead detail','${l.id}')`)}</article>`).join('')||empty('Tidak ada lead sesuai filter.')}</div><p class="hint">Lead converted tetap tersimpan. Bulan adalah filter tanggal dibuat, bukan reset lifecycle.</p>`}
else if(view==='Lead detail'){let l=db.leads.find(x=>x.id===focus);if(!l||!mine(l))h=empty('Data tidak tersedia untuk persona ini.');else {let p=profile(l.profile);h=`<div class="panel"><div class="recordtop">${badge(l.status)}${badge(p.relation)}</div><h1>${E(p.name)}</h1><p>${E(p.contact)} · ${E(p.phone)}</p><div class="facts"><div><small>Sumber</small>${E(l.source)}${l.referral?' / '+E(l.referral):''}</div><div><small>Owner</small>${E(l.owner)}</div><div><small>Minat</small>${E(l.product)}</div><div><small>Kebutuhan</small>${E(l.need)}</div></div><div class="actions">${!['Converted','Closed','CustomerConverted'].includes(l.status)?btn('Kualifikasi',`qualify('${l.id}')`,true)+btn('Tambah Task',`newTask('${p.id}','','${l.id}')`)+btn('Tutup lead',`closeLead('${l.id}')`):''}${btn('Nasabah',`go('Nasabah detail','${p.id}')`)}${btn('Reassign',`reassign('lead','${l.id}')`)}</div></div><div class="panel"><h2>Opportunity terkait</h2>${db.opps.filter(o=>o.lead===l.id&&mine(o)).map(oppCard).join('')||empty('Belum ada opportunity.')}<h2>Aktivitas</h2>${timeline(p.id)}</div>`}}
else if(view==='Peluang'){actions=btn('Opportunity baru','newOpp()',true);let a=db.opps.filter(o=>matches(o,o.name+' '+pname(o.profile))&&(!month||o.created.startsWith(month))&&(!stageFilter||o.stage===stageFilter));h=toolbar(filters()+`<select onchange="stageFilter=this.value;renderContent()"><option value="">Semua tahap</option>${options(stages,stageFilter)}</select>`)+`<div class="board">${stages.filter(s=>!stageFilter||s===stageFilter).map(s=>`<section class="column"><div class="columnhead"><b>${s}</b><span>${a.filter(o=>o.stage===s).length}</span></div>${a.filter(o=>o.stage===s).map(oppCard).join('')||'<div class="hint">Belum ada peluang</div>'}</section>`).join('')}</div>`}
else if(view==='Opportunity detail'){let o=opp(focus);if(!o||!mine(o))h=empty('Data tidak tersedia untuk persona ini.');else h=`<div class="panel"><div class="recordtop">${badge(o.stage)}${badge(o.outcome)}</div><h1>${E(o.name)}</h1><button class="textbtn" onclick="go('Nasabah detail','${o.profile}')">${E(pname(o.profile))} ↗</button><div class="facts"><div><small>Produk / kebutuhan</small>${E(o.product)}<p>${E(o.need)}</p></div><div><small>Nilai indikatif</small>${rup(o.value)}<p>${E(o.basis)}</p></div><div><small>Owner / target closing</small>${E(o.owner)}<p>${fmt(o.closing)}</p></div><div><small>Umur tahap</small>${Math.max(0,Math.floor((Date.now()-new Date(o.entered))/86400000))} hari</div></div>${o.outcome==='Aktif'?`<div class="actions">${btn('Buat next action',`newTask('${o.profile}','${o.id}')`,true)}${btn('Update tahap',`changeStage('${o.id}')`)}${btn('Reassign',`reassign('opp','${o.id}')`)}${btn('Tutup peluang',`closeOpp('${o.id}')`)}</div>`:`<p class="hint">${E(o.reason||'')} · Referensi ${E(o.reference||'-')}</p>`}</div><div class="split"><section class="panel"><h2>Tindak lanjut terbuka</h2>${nextTasks(o.id).map(taskCard).join('')||empty(o.review?'Review '+fmt(o.review)+': '+E(o.wait):'Belum ada next action.')}<h2>Riwayat aktivitas</h2>${timeline(o.profile,o.id)}</section><section class="panel"><h2>Riwayat perubahan</h2>${history(o.id)}</section></div>`}
else if(view==='Agenda'){actions=btn('Task baru','newTask()',true);let ts=db.tasks.filter(t=>matches(t,pname(t.profile)+' '+t.purpose)&&(statusFilter==='Overdue'?overdue(t):statusFilter==='Selesai'?t.status==='Selesai':statusFilter==='Semua'?true:isOpen(t)));h=toolbar(`<select onchange="statusFilter=this.value;renderContent()">${options(['Aktif','Overdue','Selesai','Semua'],statusFilter)}</select>`)+`<div class="records">${ts.sort((a,b)=>a.scheduled.localeCompare(b.scheduled)).map(taskCard).join('')||empty('Agenda kosong untuk filter ini.')}</div>`}
else if(view==='Aktivitas detail'){let t=task(focus);if(!t||!mine(t))h=empty('Data tidak tersedia.');else h=`<div class="panel"><div class="recordtop">${badge(t.type)}${badge(overdue(t)?'Overdue':t.status)}</div><h1>${E(t.purpose)}</h1><p>${E(pname(t.profile))} · ${E(t.owner)}</p><div class="facts"><div><small>Jadwal</small>${fmt(t.scheduled)}</div><div><small>Deadline</small>${fmt(t.due)}</div></div><div class="actions">${taskIdentityButton(t)}${t.opp?btn('Opportunity',`go('Opportunity detail','${t.opp}')`):''}</div>${isOpen(t)?`<div class="activitybox">${activityKind(t.type)==='Telepon'?`<a class="button primary" href="tel:${E(profile(t.profile).phone)}">Buka dialer</a><p class="hint">Setelah menelepon, catat hasil dan tindakan berikutnya.</p>`:activityKind(t.type)==='Kunjungan'?`<h2>Pelaksanaan kunjungan</h2>${!t.checkin?`<div class="actions">${btn('Check-in GPS',`checkin('${t.id}')`,true)}</div>`:`<p>Check-in ${fmt(t.checkin)}</p><p class="hint">${E(t.location)}</p><label class="upload">Tambah foto<input type="file" accept="image/*" capture="environment" onchange="addPhoto('${t.id}',this)"></label>${t.photo?`<img class="photo" alt="Foto kunjungan" src="${t.photo}">`:''}`}`:''}<div class="actions">${activityKind(t.type)!=='Kunjungan'||t.checkin?btn(activityKind(t.type)==='Kunjungan'?'Check-out & laporan':'Catat hasil',`activityForm('${t.id}')`,true):''}${btn('Reschedule',`reschedule('${t.id}')`)}${btn('Reassign',`reassign('task','${t.id}')`)}</div></div>`:`<p class="hint">Aktivitas ditutup. Hasil dapat dibaca pada timeline profil.</p>`}</div><div class="panel"><h2>Riwayat task</h2>${history(t.id)}</div>`}
else if(view==='Nasabah'){h=toolbar()+`<div class="records">${db.profiles.filter(p=>matches(p,p.name+' '+p.contact)).map(p=>`<article class="record"><div class="recordtop">${badge(p.relation)}<span class="label">${E(p.owner)}</span></div><h3>${E(p.name)}</h3><p>${E(p.contact)} · ${E(p.phone)}</p><div class="meta">${db.opps.filter(o=>o.profile===p.id&&o.outcome==='Aktif').length} peluang aktif</div><div class="actions">${btn('Buka profil',`go('Nasabah detail','${p.id}')`)}${btn('Opportunity baru',`newOpp('${p.id}')`)}</div></article>`).join('')||empty('Belum ada nasabah yang sesuai dengan pencarian.')}</div>`}
else if(view==='Nasabah detail'){let p=profile(focus);if(!p||!mine(p))h=empty('Profil di luar akses persona.');else h=`<div class="panel"><div class="recordtop">${badge(p.relation)}<span class="label">IDENTITAS TUNGGAL</span></div><h1>${E(p.name)}</h1><p>${E(p.contact)} · ${E(p.phone)}</p><div class="facts"><div><small>Alamat</small>${E(p.address||'-')}</div><div><small>Owner</small>${E(p.owner)}</div></div><div class="actions">${btn('Opportunity baru',`newOpp('${p.id}')`,true)}${btn('Tambah Task',`newTask('${p.id}')`)}${p.relation==='Prospect'?btn('Konfirmasi Customer',`confirmCustomer('${p.id}')`):''}</div></div><div class="tabs">${['Ringkasan','Opportunity','Aktivitas','Agenda'].map(t=>`<button class="${activeTab===t?'active':''}" onclick="activeTab='${t}';renderContent()">${t}</button>`).join('')}</div><div class="panel">${activeTab==='Opportunity'?db.opps.filter(o=>o.profile===p.id&&mine(o)).map(oppCard).join('')||empty('Belum ada peluang.'):activeTab==='Aktivitas'?timeline(p.id):activeTab==='Agenda'?db.tasks.filter(t=>t.profile===p.id&&mine(t)&&isOpen(t)).map(taskCard).join('')||empty('Tidak ada task terbuka.'):`<h2>Ringkasan hubungan</h2><p>Profil ini memiliki ${db.opps.filter(o=>o.profile===p.id).length} opportunity dan ${db.activities.filter(a=>a.profile===p.id).length} aktivitas tercatat.</p><p class="hint">Gunakan tab Opportunity, Aktivitas dan Agenda untuk melihat seluruh hubungan.</p><h2>Aktivitas terbaru</h2>${timeline(p.id)}`}</div>`}
else if(view==='Riwayat'){h=`<section class="panel"><h2>Riwayat perubahan</h2>${history()}</section>`}
else if(view==='Pengaturan'||view==='Lainnya'){h=`<div class="panel"><h2>Scope versi fokus</h2><p>Lead dan opportunity, aktivitas/follow-up, profil ringkas serta monitoring. Tidak mencakup AI, campaign, approval kredit, pencairan, health score, territory atau attendance.</p><div class="actions">${btn('Monitoring',"go('Monitoring')")}${btn('Riwayat',"go('Riwayat')")}</div></div><div class="panel"><h2>Aturan monitoring</h2><p>Stage stagnan setelah ${db.config.aging} hari. Timezone tampilan mengikuti perangkat pada prototype.</p>${btn('Ubah ambang',"configForm()")}</div><div class="panel"><h2>Impor dan ekspor data</h2><p>CMS dan mobile ini memakai penyimpanan browser terpisah. Ekspor lalu impor untuk melanjutkan skenario yang sama. Ini bukan sinkronisasi backend.</p><div class="actions">${btn('Ekspor data','exportData()')}<label class="button">Impor data<input hidden type="file" accept="application/json" onchange="importData(this)"></label>${btn('Reset demo','resetDemo()')}</div></div>`}
$('#app').innerHTML=`${!['Monitoring','Lead detail','Opportunity detail','Aktivitas detail','Nasabah detail'].includes(view)?`<div class="intro"><div><span class="label">CRM FOCUS</span><h1>${E(view)}</h1><p>${{Leads:'Calon hubungan dan kebutuhan awal.',Peluang:'Kelola kebutuhan menjadi potensi kesepakatan.',Agenda:'Tindakan berikutnya untuk setiap peluang.',Profil:'Lead dan customer, satu riwayat yang utuh.'}[view]||'Preferensi dan konfigurasi workspace.'}</p></div>${actions}</div>`:''}${h}`;
}
function history(id=''){let a=db.audit.filter(a=>!id||a.object===id);return a.map(a=>`<div class="miniitem"><b>${E(a.action)}</b><p>${E(a.detail)}</p><small>${fmt(a.time)} · ${E(a.actor)} · ${E(a.object)}</small></div>`).join('')||empty('Belum ada perubahan tercatat.')}
function showException(kind){go('Peluang');let a=visible(db.opps).filter(o=>o.outcome==='Aktif'&&(kind==='next'?!hasNext(o):(Date.now()-new Date(o.entered))/86400000>db.config.aging));$('#app').innerHTML=`<div class="intro"><h1>${kind==='next'?'Tanpa next action':'Peluang stagnan'}</h1></div><div class="records">${a.map(oppCard).join('')||empty('Tidak ada exception.')}</div>`}
function configForm(){if(!supervisors())return toast('Konfigurasi untuk supervisor/admin');modal('Ambang stage aging',field('Jumlah hari','aging',db.config.aging,'number',true),f=>{if(Number(f.aging)<1)throw Error('Minimal satu hari');db.config.aging=Number(f.aging);record('Update konfigurasi','config','Stage aging '+f.aging+' hari')})}
function exportData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='jarivis-focus-demo.json';a.click();URL.revokeObjectURL(a.href)}
function importData(input){let f=input.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);for(let k of ['profiles','leads','opps','tasks','activities','audit'])if(!Array.isArray(d[k]))throw Error('Format tidak sesuai');if(d.version!==1)throw Error('Versi tidak sesuai');db=d;record('Impor data','demo');go(mobile?'Agenda':'Monitoring');toast('Data berhasil diimpor')}catch(e){toast(e.message)}};r.readAsText(f)}
function resetDemo(){modal('Pulihkan data awal','<p>Data pada perangkat ini akan dikembalikan ke data awal.</p>',()=>{db=seed();localStorage.setItem(key,JSON.stringify(db));go(mobile?'Agenda':'Monitoring')})}
